SELECT DISTINCT m.chembl_id AS chembl_id, r.compound_name AS compound_name, cs.canonical_smiles AS canonical_smiles FROM molecule_dictionary m JOIN compound_records r ON m.molregno = r.molregno JOIN docs d ON r.doc_id = d.doc_id JOIN compound_structures cs ON m.molregno = cs.molregno WHERE d.chembl_id = 'CHEMBL3639333' ORDER BY m.chembl_id, r.compound_name, cs.canonical_smiles
